// "Same link" rule: lower-case only the scheme and host (which are
// case-insensitive) and drop a harmless trailing slash. Keep the path and
// query exactly as typed; keep http vs https and www vs non-www distinct.
function normalize(url) {
  var raw = url.trim();
  try {
    var u = new URL(raw);
    var path = u.pathname.replace(/\/+$/, "");
    return u.protocol.toLowerCase() + "//" + u.hostname.toLowerCase() +
      (u.port ? ":" + u.port : "") + path + u.search;
  } catch (e) {
    return raw.replace(/\/+$/, "");
  }
}

