// Supports quoted phrases ("..."), AND / OR / NOT operators, parentheses for
// grouping, and implicit AND between adjacent terms. Words are matched
// case-insensitively as substrings across a bookmark's searchable text.
// Operator words only act as operators when unquoted; "and" in quotes is literal.
var currentQuery = "";
function hayFor(it) { return (it.title + " " + it.description + " " + it.url).toLowerCase(); }

function tokenize(s) {
  var toks = [], i = 0, n = s.length;
  while (i < n) {
    var c = s[i];
    if (c === " " || c === "\t") { i++; continue; }
    if (c === "(") { toks.push({ type: "LP" }); i++; continue; }
    if (c === ")") { toks.push({ type: "RP" }); i++; continue; }
    if (c === '"') {
      var j = i + 1, buf = "";
      while (j < n && s[j] !== '"') { buf += s[j]; j++; }
      i = (j < n) ? j + 1 : j;
      if (buf.trim().length) toks.push({ type: "TERM", value: buf.toLowerCase() });
      continue;
    }
    var k = i, w = "";
    while (k < n && s[k] !== " " && s[k] !== "\t" && s[k] !== "(" && s[k] !== ")" && s[k] !== '"') { w += s[k]; k++; }
    i = k;
    if (!w.length) continue;
    var up = w.toUpperCase();
    if (up === "AND") toks.push({ type: "AND" });
    else if (up === "OR") toks.push({ type: "OR" });
    else if (up === "NOT") toks.push({ type: "NOT" });
    else toks.push({ type: "TERM", value: w.toLowerCase() });
  }
  return toks;
}

function compileQuery(input) {
  var tokens = tokenize(input), pos = 0;
  function peek() { return tokens[pos]; }
  function atom() {
    var t = peek();
    if (!t) return null;
    if (t.type === "LP") { pos++; var e = parseOr(); if (peek() && peek().type === "RP") pos++; return e; }
    if (t.type === "RP") return null;
    if (t.type === "AND" || t.type === "OR") { pos++; return atom(); } // stray operator: skip
    if (t.type === "NOT") { pos++; var a = atom(); return a ? function (h) { return !a(h); } : null; }
    pos++; var term = t.value; return function (h) { return h.indexOf(term) >= 0; };
  }
  function parseAnd() {
    var left = atom();
    while (peek()) {
      var t = peek();
      if (t.type === "RP" || t.type === "OR") break;
      if (t.type === "AND") pos++;
      var right = atom();
      if (right) { var l = left, r = right; left = l ? function (h) { return l(h) && r(h); } : r; }
    }
    return left;
  }
  function parseOr() {
    var left = parseAnd();
    while (peek() && peek().type === "OR") {
      pos++; var right = parseAnd();
      if (right) { var l = left, r = right; left = l ? function (h) { return l(h) || r(h); } : r; }
    }
    return left;
  }
  return parseOr();
}

function buildMatcher(raw) {
  try { var m = compileQuery(raw); if (m) return m; } catch (e) {}
  var t = raw.toLowerCase();
  return function (h) { return h.indexOf(t) >= 0; };
}

// ---- rendering ----
function render(highlightId) {
  var all = load();
  var raw = currentQuery.trim();
  var matcher = raw ? buildMatcher(raw) : null;
  var items = matcher ? all.filter(function (it) { return matcher(hayFor(it)); }) : all;
  var list = document.getElementById("list");
  var count = document.getElementById("count");
  list.innerHTML = "";
  if (all.length === 0) {
    count.textContent = "";
    list.innerHTML = '<div class="empty"><div class="big">🔖</div>Nothing saved yet. Paste a link above and press Save.</div>';
    return;
  }
  if (items.length === 0) {
    count.textContent = "";
    list.innerHTML = '<div class="empty"><div class="big">🔍</div><span id="noRes"></span></div>';
    document.getElementById("noRes").textContent = "No saved links match “" + raw + "”.";
    return;
  }
  count.textContent = raw ? (items.length + " of " + all.length + " links match")
                          : (all.length + (all.length === 1 ? " saved link" : " saved links"));

