function isRead(it) { return it.read === true; }

// ---- rendering ----
function render(highlightId) {
  var all = load();
  var raw = currentQuery.trim();
  var matcher = raw ? buildMatcher(raw) : null;
  var matched = matcher ? all.filter(function (it) { return matcher(hayFor(it)); }) : all;

  var nUnread = matched.filter(function (it) { return !isRead(it); }).length;
  var nRead = matched.length - nUnread;
  setFilterLabel("all", "All", matched.length);
  setFilterLabel("unread", "To read", nUnread);
  setFilterLabel("read", "Read", nRead);

  var items = matched.filter(function (it) {
    if (currentFilter === "unread") return !isRead(it);
    if (currentFilter === "read") return isRead(it);
    return true;
  });

  var list = document.getElementById("list");
  var count = document.getElementById("count");
  list.innerHTML = "";

  if (all.length === 0) {
    count.textContent = "";
    list.innerHTML = '<div class="empty"><div class="big">🔖</div>Nothing saved yet. Paste a link above and press Save.</div>';
    return;
  }
  if (items.length === 0) {
    count.textContent = "";
    var icon = "🔍", msg;
    if (raw && matched.length === 0) { msg = "No saved links match “" + raw + "”."; }
    else if (currentFilter === "unread") { icon = "🎉"; msg = raw ? "Nothing left to read in these results." : "You're all caught up — nothing left to read."; }
    else if (currentFilter === "read") { icon = "📖"; msg = raw ? "Nothing here is marked as read yet." : "Nothing marked as read yet."; }
    else { msg = "No links to show."; }
    list.innerHTML = '<div class="empty"><div class="big">' + icon + '</div><span id="noRes"></span></div>';
    document.getElementById("noRes").textContent = msg;
    return;
  }

  var parts = [items.length + (items.length === 1 ? " link" : " links")];
  if (currentFilter === "all") parts.push(nUnread + " to read");
  count.textContent = parts.join(" · ") + (raw ? " (filtered by search)" : "");

  items.forEach(function (it) {
    var li = document.createElement("li");
    li.className = "item" + (isRead(it) ? " read" : "") + (it.id === highlightId ? " flash-existing" : "");
    li.innerHTML =
      '<div class="thumb"></div>' +
      '<div class="body">' +
        '<a class="open" href="' + it.url + '" target="_blank" rel="noopener">' +
          '<div class="titleRow"><span class="fav"></span><span class="title"></span></div>' +
          '<p class="desc"></p>' +
          '<div class="url"></div>' +
        '</a>' +
        '<div class="actions">' +
          '<button class="readBtn' + (isRead(it) ? ' done' : '') + '" data-read="' + it.id + '"></button>' +
          '<button data-edit="' + it.id + '">Edit</button>' +
        '</div>' +
      '</div>';
    li.querySelector(".thumb").style.backgroundImage = svgPreview(it.preview.label, it.preview.color);
    var fav = li.querySelector(".fav");
    fav.textContent = it.icon.letter; fav.style.background = it.icon.color;
    li.querySelector(".title").textContent = it.title;
    li.querySelector(".desc").textContent = it.description;
    li.querySelector(".url").textContent = it.url;
    li.querySelector(".readBtn").textContent = isRead(it) ? "✓ Read" : "Mark as read";
    list.appendChild(li);
  });

  list.querySelectorAll("button[data-edit]").forEach(function (b) {
    b.addEventListener("click", function () {
      var id = b.getAttribute("data-edit");
      var item = load().filter(function (x) { return x.id === id; })[0];
      if (item) openEditExisting(item);
    });
  });
  list.querySelectorAll("button[data-read]").forEach(function (b) {
    b.addEventListener("click", function () {
      var id = b.getAttribute("data-read");
      var items2 = load(), changed = null;
      for (var i = 0; i < items2.length; i++) {
        if (items2[i].id === id) { items2[i].read = !items2[i].read; changed = items2[i]; }
      }
      persist(items2);
      render();
      if (changed) flash(changed.read ? "Marked as read." : "Moved back to “to read”.", "ok");
    });
  });
}

function setFilterLabel(key, label, n) {
  var b = document.querySelector('.filters button[data-filter="' + key + '"]');
  if (b) b.textContent = label + " (" + n + ")";
}

