document.getElementById("mSave").addEventListener("click", function () {
  var title = document.getElementById("mTitle").value.trim();
  var desc = document.getElementById("mDesc").value.trim();
  var url = document.getElementById("mUrl").value.trim();
  var errBox = document.getElementById("mErr");
  errBox.textContent = "";
  if (!url) { errBox.textContent = "Please enter a web address."; return; }
  if (!isValidWebUrl(url)) {
    errBox.textContent = "That doesn't look like a valid web link. It should start with http:// or https://";
    return;
  }
  var norm = normalize(url);
  var items = load();

  // Guard: the corrected address must not collide with a different saved link.
  var clash = items.filter(function (x) { return x.norm === norm && x.id !== editState.id; })[0];
  if (clash) {
    errBox.textContent = "Another saved bookmark already uses this address (“" + clash.title + "”).";
    return;
  }

  if (editState.mode === "new") {
    items.unshift({
      id: "b" + Date.now(),
      url: url,
      norm: norm,
      title: title || editState.meta.title,
      description: desc,
      icon: editState.meta.icon,
      preview: editState.meta.preview,
      read: false,
      savedAt: Date.now()
    });
    persist(items);
    hideModal();
    render();
    flash("Saved “" + (title || editState.meta.title) + "”.", "ok");
  } else {
