// ---- existing-tag suggestions ----
var suggestList = [], suggestActive = -1;
function allUsedTags() {
  var set = {}, out = [];
  load().forEach(function (it) { (it.tags || []).forEach(function (t) { set[String(t).toLowerCase()] = true; }); });
  for (var k in set) out.push(k);
  return out;
}
function hideSuggest() {
  var el = document.getElementById("tagSuggest");
  el.classList.remove("show"); el.innerHTML = "";
  suggestList = []; suggestActive = -1;
}
function updateSuggest() {
  var field = document.getElementById("mTagField");
  var q = field.value.trim().toLowerCase().replace(/^#+/, "");
  var el = document.getElementById("tagSuggest");
  if (!q) { hideSuggest(); return; }
  var pool = allUsedTags().filter(function (t) { return t.indexOf(q) >= 0 && draftTags.indexOf(t) < 0; });
  pool.sort(function (a, b) {
    var sa = a.indexOf(q) === 0 ? 0 : 1, sb = b.indexOf(q) === 0 ? 0 : 1;
    return sa !== sb ? sa - sb : a.localeCompare(b);
  });
  suggestList = pool.slice(0, 8);
  if (!suggestList.length) { hideSuggest(); return; }
  suggestActive = 0;
  el.innerHTML = "";
  suggestList.forEach(function (t, i) {
    var opt = document.createElement("div");
    opt.className = "opt" + (i === 0 ? " active" : "");
    opt.textContent = "#" + t;
    opt.addEventListener("mousedown", function (e) { e.preventDefault(); addTag(t); field.focus(); });
    el.appendChild(opt);
  });
  el.classList.add("show");
}
function moveActive(delta) {
  if (!suggestList.length) return;
  suggestActive = (suggestActive + delta + suggestList.length) % suggestList.length;
  var opts = document.getElementById("tagSuggest").querySelectorAll(".opt");
  opts.forEach(function (o, i) { o.classList.toggle("active", i === suggestActive); });
}
document.getElementById("mTagField").addEventListener("input", updateSuggest);
document.getElementById("mTagField").addEventListener("keydown", function (e) {
  var open = suggestList.length > 0;
  if (e.key === "ArrowDown") { if (open) { e.preventDefault(); moveActive(1); } }
  else if (e.key === "ArrowUp") { if (open) { e.preventDefault(); moveActive(-1); } }
  else if (e.key === "Enter" || e.key === ",") {
    e.preventDefault();
    if (open && suggestActive >= 0) addTag(suggestList[suggestActive]);
    else addTagFromField();
  }
  else if (e.key === "Escape") { hideSuggest(); }
  else if (e.key === "Backspace" && !this.value && draftTags.length) { draftTags.pop(); renderTagChips(); }
});
document.getElementById("mTagField").addEventListener("blur", function () {
  setTimeout(function () { addTagFromField(); }, 120);
});

