// ---- modal / editor ----
var overlay = document.getElementById("overlay");
var editState = { mode: null, id: null, url: null, meta: null };

// ---- tag editor ----
var draftTags = [];
function normalizeTag(s) {
  var t = String(s).trim().replace(/^#+/, "").toLowerCase().replace(/\s+/g, "-");
  return t.length ? t : null;
}
function renderTagChips() {
  var box = document.getElementById("mTagInput");
  box.querySelectorAll(".tagChip").forEach(function (c) { c.remove(); });
  var field = document.getElementById("mTagField");
  draftTags.forEach(function (tg, idx) {
    var chip = document.createElement("span");
    chip.className = "tagChip";
    var label = document.createElement("span");
    label.textContent = "#" + tg;
    var x = document.createElement("button");
    x.type = "button"; x.textContent = "×";
    x.addEventListener("click", function () { draftTags.splice(idx, 1); renderTagChips(); });
    chip.appendChild(label); chip.appendChild(x);
    box.insertBefore(chip, field);
  });
}
function addTag(tag) {
  var n = normalizeTag(tag);
  if (n && draftTags.indexOf(n) < 0) draftTags.push(n);
  var field = document.getElementById("mTagField");
  field.value = "";
  renderTagChips();
  hideSuggest();
}
function addTagFromField() { addTag(document.getElementById("mTagField").value); }

// ---- existing-tag suggestions ----
var suggestList = [], suggestActive = -1;

