function openAddFlow(url) {
  showLoading();
  setTimeout(function () {
    var meta = fakeFetch(url);
    editState = { mode: "new", id: null, url: url, meta: meta };
    fillForm("Review & save", meta, url);
    if (meta.failed) {
      var notice = document.getElementById("mNotice");
      notice.textContent = "We couldn't fetch this page's details. You can still save it and fill in the title and description yourself.";
      notice.style.display = "block";
    }
    var row = document.getElementById("readLaterRow");
    row.style.display = "flex";
    document.getElementById("mReadLater").checked = false; // default: deliberate opt-in
    draftTags = []; document.getElementById("mTagField").value = ""; hideSuggest(); renderTagChips();
    document.getElementById("mTitle").focus();
  }, 650);
}

function openEditExisting(item) {
  editState = { mode: "edit", id: item.id, url: item.url,
    meta: { title: item.title, description: item.description, icon: item.icon, preview: item.preview } };
  fillForm("Edit bookmark", editState.meta, item.url);
  document.getElementById("readLaterRow").style.display = "none";
  draftTags = (item.tags || []).slice(); document.getElementById("mTagField").value = ""; hideSuggest(); renderTagChips();
  showModal();
}

