document.getElementById("saver").addEventListener("submit", function (e) {
  e.preventDefault();
  var input = document.getElementById("urlInput");
  var url = input.value.trim();
  if (!url) return;
  var norm = normalize(url);
  var existing = load().filter(function (x) { return x.norm === norm; })[0];
  if (existing) {
    input.value = "";
    flash("You already saved this link — opening it so you can edit.", "info");
    render(existing.id);
    openEditExisting(existing);
    var el = document.querySelector(".flash-existing");
    if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
    return;
  }
  input.value = "";
  openAddFlow(url);
});

document.getElementById("searchInput").addEventListener("input", function (e) {
  currentQuery = e.target.value;
  visibleCount = PAGE_SIZE;
  render();
});

document.querySelectorAll('.filters button[data-filter]').forEach(function (b) {
  b.addEventListener("click", function () {
    currentFilter = b.getAttribute("data-filter");
    document.querySelectorAll(".filters button").forEach(function (x) { x.classList.remove("active"); });
    b.classList.add("active");
    visibleCount = PAGE_SIZE;
    render();
  });
});

