// ---- delete confirmation ----
var confirmOverlay = document.getElementById("confirmOverlay");
var pendingDeleteId = null;
function askDelete(id) {
  pendingDeleteId = id;
  var it = load().filter(function (x) { return x.id === id; })[0];
  document.getElementById("confirmBody").textContent =
    (it ? "“" + it.title + "” will be permanently deleted. " : "") +
    "This can't be undone. If you might want it later, archive it instead.";
  confirmOverlay.classList.add("show");
}
function closeConfirm() { confirmOverlay.classList.remove("show"); pendingDeleteId = null; }
document.getElementById("confirmCancel").addEventListener("click", closeConfirm);
confirmOverlay.addEventListener("click", function (e) { if (e.target === confirmOverlay) closeConfirm(); });
document.getElementById("confirmDelete").addEventListener("click", function () {
  if (!pendingDeleteId) return;
  var arr = load().filter(function (x) { return x.id !== pendingDeleteId; });
  persist(arr);
  closeConfirm();
  render();
  flash("Bookmark deleted.", "ok");
});

