// ---- minimal, safe Markdown for notes (links, emphasis, headings, lists) ----
function escapeHtml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function inlineMd(s) {
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, function (m, text, url) {
    return /^(https?:\/\/|mailto:)/i.test(url) ? '<a href="' + url + '" target="_blank" rel="noopener">' + text + "</a>" : m;
  });
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>").replace(/__([^_]+)__/g, "<strong>$1</strong>");
  s = s.replace(/\*([^*]+)\*/g, "<em>$1</em>").replace(/_([^_]+)_/g, "<em>$1</em>");
  return s;
}
function mdToHtml(md) {
  var lines = escapeHtml(md).split(/\r?\n/);
  var out = [], i = 0;
  while (i < lines.length) {
    var line = lines[i];
    var h = /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) { var lvl = h[1].length; out.push("<h" + lvl + ">" + inlineMd(h[2]) + "</h" + lvl + ">"); i++; continue; }
    if (/^\s*[-*]\s+/.test(line)) {
      out.push("<ul>");
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) { out.push("<li>" + inlineMd(lines[i].replace(/^\s*[-*]\s+/, "")) + "</li>"); i++; }
      out.push("</ul>"); continue;
    }
    if (/^\s*\d+\.\s+/.test(line)) {
      out.push("<ol>");
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) { out.push("<li>" + inlineMd(lines[i].replace(/^\s*\d+\.\s+/, "")) + "</li>"); i++; }
      out.push("</ol>"); continue;
    }
    if (/^\s*$/.test(line)) { i++; continue; }
    var para = [];
    while (i < lines.length && !/^\s*$/.test(lines[i]) && !/^(#{1,6})\s+/.test(lines[i]) && !/^\s*[-*]\s+/.test(lines[i]) && !/^\s*\d+\.\s+/.test(lines[i])) {
      para.push(inlineMd(lines[i])); i++;
    }
    out.push("<p>" + para.join("<br>") + "</p>");
  }
  return out.join("");
}
function mdToPlain(md) {
  return String(md)
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^\s*[-*]\s+/gm, "• ")
    .replace(/^\s*\d+\.\s+/gm, "")
    .replace(/\*\*([^*]+)\*\*/g, "$1").replace(/__([^_]+)__/g, "$1")
    .replace(/\*([^*]+)\*/g, "$1").replace(/_([^_]+)_/g, "$1")
    .replace(/\s+/g, " ").trim();
}

