// ---- bulk actions ----
document.getElementById("selectBtn").addEventListener("click", function () {
  selectMode = !selectMode;
  selectedIds = {};
  this.classList.toggle("on", selectMode);
  this.textContent = selectMode ? "Done" : "Select";
  render();
});
document.getElementById("bulkCancel").addEventListener("click", function () {
  selectMode = false; selectedIds = {};
  var sb = document.getElementById("selectBtn"); sb.classList.remove("on"); sb.textContent = "Select";
  render();
});
document.getElementById("bulkSelectAll").addEventListener("click", function () {
  var allSelected = currentFilteredIds.length > 0 && currentFilteredIds.every(function (id) { return selectedIds[id]; });
  selectedIds = {};
  if (!allSelected) currentFilteredIds.forEach(function (id) { selectedIds[id] = true; });
  render();
});
function applyToSelected(fn, verbPastTense) {
  var ids = selectedIds, n = 0, arr = load();
  for (var i = 0; i < arr.length; i++) { if (ids[arr[i].id]) { fn(arr[i]); n++; } }
  persist(arr); selectedIds = {}; render();
  flash(n + (n === 1 ? " link " : " links ") + verbPastTense + ".", "ok");
}
document.querySelectorAll('.bulkBar button[data-bulk]').forEach(function (b) {
  b.addEventListener("click", function () {
    var action = b.getAttribute("data-bulk");
    if (selectedCount() === 0 && action !== "addtag") { flash("Select some links first.", "info"); return; }
    if (action === "readlater") applyToSelected(function (it) { it.toRead = true; delete it.read; }, "added to Read later");
    else if (action === "read") applyToSelected(function (it) { it.toRead = false; delete it.read; }, "marked as read");
    else if (action === "archive") applyToSelected(function (it) { it.archived = true; }, "archived");
    else if (action === "restore") applyToSelected(function (it) { it.archived = false; }, "restored");
    else if (action === "addtag") {
      var field = document.getElementById("bulkTagField");
      var tag = normalizeTag(field.value);
      if (!tag) { flash("Type a tag to add.", "info"); return; }
      if (selectedCount() === 0) { flash("Select some links first.", "info"); return; }
      applyToSelected(function (it) {
        it.tags = it.tags || [];
        if (it.tags.indexOf(tag) < 0) it.tags.push(tag);
      }, "tagged “#" + tag + "”");
      field.value = "";
    }
    else if (action === "delete") askBulkDelete();
  });
});
function askBulkDelete() {
  var n = selectedCount();
  pendingDeleteId = "__BULK__";
  document.getElementById("confirmBody").textContent =
    n + (n === 1 ? " bookmark" : " bookmarks") + " will be permanently deleted. This can't be undone. If you might want them later, archive instead.";
  confirmOverlay.classList.add("show");
}

// ---- settings panel ----
