// ---- saved views ----
// A view remembers the current search (which may include or exclude #tags),
// the list filter, and the sort. Opening it recomputes live, so newly saved
// links that match will appear automatically.
var VIEWS_KEY = "bm_proto_views";
function loadViews() { try { return JSON.parse(localStorage.getItem(VIEWS_KEY)) || []; } catch (e) { return []; } }
function saveViews() { localStorage.setItem(VIEWS_KEY, JSON.stringify(savedViews)); }
var savedViews = loadViews();
function labelForFilter(f) { return f === "unread" ? "To read" : f === "read" ? "Read" : f === "archived" ? "Archived" : "All"; }
function labelForSort(s) {
  return s === "added-asc" ? "Oldest first" : s === "title-asc" ? "Title A–Z" : s === "title-desc" ? "Title Z–A" : "Newest first";
}
function describeView(v) {
  var parts = [];
  parts.push(v.query ? "Search: “" + v.query + "”" : "Search: (none)");
  parts.push("Filter: " + labelForFilter(v.filter));
  parts.push("Sort: " + labelForSort(v.sort));
  return parts.join(" · ");
}
function renderViewsChips() {
  var box = document.getElementById("viewsChips");
  box.innerHTML = "";
  savedViews.forEach(function (v) {
    var chip = document.createElement("span");
    chip.className = "viewChip";
    var open = document.createElement("button");
    open.className = "open"; open.type = "button"; open.textContent = v.name;
    open.title = describeView(v);
    open.addEventListener("click", function () { applyView(v); });
    var del = document.createElement("button");
    del.className = "del"; del.type = "button"; del.textContent = "×"; del.title = "Delete this view";
    del.addEventListener("click", function () {
      savedViews = savedViews.filter(function (x) { return x.id !== v.id; });
      saveViews(); renderViewsChips(); flash("View “" + v.name + "” removed.", "ok");
    });
    chip.appendChild(open); chip.appendChild(del);
    box.appendChild(chip);
  });
}
function applyView(v) {
  var box = document.getElementById("searchInput");
  box.value = v.query; currentQuery = v.query;
  currentFilter = v.filter;
  document.querySelectorAll(".filters button").forEach(function (x) {
    x.classList.toggle("active", x.getAttribute("data-filter") === v.filter);
  });
  currentSort = v.sort;
  document.getElementById("sortSelect").value = v.sort;
  visibleCount = PAGE_SIZE;
  render();
  flash("Opened view “" + v.name + "”.", "ok");
}
var viewOverlay = document.getElementById("viewOverlay");
document.getElementById("saveViewBtn").addEventListener("click", function () {
  document.getElementById("viewName").value = "";
  document.getElementById("viewErr").textContent = "";
  document.getElementById("viewSummary").textContent =
    describeView({ query: currentQuery.trim(), filter: currentFilter, sort: currentSort });
  viewOverlay.classList.add("show");
  document.getElementById("viewName").focus();
});
document.getElementById("viewCancel").addEventListener("click", function () { viewOverlay.classList.remove("show"); });
viewOverlay.addEventListener("click", function (e) { if (e.target === viewOverlay) viewOverlay.classList.remove("show"); });
document.getElementById("viewSave").addEventListener("click", function () {
  var name = document.getElementById("viewName").value.trim();
  if (!name) { document.getElementById("viewErr").textContent = "Please give the view a name."; return; }
  savedViews.push({ id: "v" + Date.now(), name: name, query: currentQuery.trim(), filter: currentFilter, sort: currentSort });
  saveViews(); renderViewsChips();
  viewOverlay.classList.remove("show");
  flash("View “" + name + "” saved.", "ok");
});

