  }
  var clr = document.createElement("button"); clr.className = "clearTags"; clr.type = "button"; clr.textContent = "Clear tag filters";
  clr.addEventListener("click", function () { currentIncludeTags = []; currentExcludeTags = []; visibleCount = PAGE_SIZE; render(); });
  bar.appendChild(clr);
  bar.style.display = "flex";
}

