function describeView(v) {
  var parts = [];
  parts.push(v.query ? "Search: “" + v.query + "”" : "Search: (none)");
  if (v.includeTags && v.includeTags.length) parts.push("Include: " + v.includeTags.map(function (t) { return "#" + t; }).join(" "));
  if (v.excludeTags && v.excludeTags.length) parts.push("Exclude: " + v.excludeTags.map(function (t) { return "#" + t; }).join(" "));
  parts.push("Filter: " + labelForFilter(v.filter));
  parts.push("Sort: " + labelForSort(v.sort));
  return parts.join(" · ");
}

// Reusable tag input with existing-tag suggestions (used by the saved-view dialog).
function makeTagPicker(wrapId, inputId, suggestId, onChange) {
  var tags = [], listS = [], activeS = -1;
  var wrap = document.getElementById(wrapId);
  var input = document.getElementById(inputId);
  var suggest = document.getElementById(suggestId);
  function renderChips() {
    wrap.querySelectorAll(".tagChip").forEach(function (c) { c.remove(); });
    tags.forEach(function (tg, idx) {
      var chip = document.createElement("span"); chip.className = "tagChip";
      var label = document.createElement("span"); label.textContent = "#" + tg;
      var x = document.createElement("button"); x.type = "button"; x.textContent = "×";
      x.addEventListener("click", function () { tags.splice(idx, 1); renderChips(); if (onChange) onChange(); });
      chip.appendChild(label); chip.appendChild(x);
      wrap.insertBefore(chip, input);
    });
    if (onChange) onChange();
  }
  function hide() { suggest.classList.remove("show"); suggest.innerHTML = ""; listS = []; activeS = -1; }
  function add(t) { var n = normalizeTag(t); if (n && tags.indexOf(n) < 0) tags.push(n); input.value = ""; renderChips(); hide(); }
  function update() {
    var q = input.value.trim().toLowerCase().replace(/^#+/, "");
    if (!q) { hide(); return; }
    var pool = allUsedTags().filter(function (t) { return t.indexOf(q) >= 0 && tags.indexOf(t) < 0; });
    pool.sort(function (a, b) { var sa = a.indexOf(q) === 0 ? 0 : 1, sb = b.indexOf(q) === 0 ? 0 : 1; return sa !== sb ? sa - sb : a.localeCompare(b); });
    listS = pool.slice(0, 8);
    if (!listS.length) { hide(); return; }
    activeS = 0; suggest.innerHTML = "";
    listS.forEach(function (t, i) {
      var opt = document.createElement("div"); opt.className = "opt" + (i === 0 ? " active" : ""); opt.textContent = "#" + t;
      opt.addEventListener("mousedown", function (e) { e.preventDefault(); add(t); input.focus(); });
      suggest.appendChild(opt);
    });
    suggest.classList.add("show");
  }
  function move(d) { if (!listS.length) return; activeS = (activeS + d + listS.length) % listS.length; suggest.querySelectorAll(".opt").forEach(function (o, i) { o.classList.toggle("active", i === activeS); }); }
  input.addEventListener("input", update);
  input.addEventListener("keydown", function (e) {
    var open = listS.length > 0;
    if (e.key === "ArrowDown") { if (open) { e.preventDefault(); move(1); } }
    else if (e.key === "ArrowUp") { if (open) { e.preventDefault(); move(-1); } }
    else if (e.key === "Enter" || e.key === ",") { e.preventDefault(); if (open && activeS >= 0) add(listS[activeS]); else if (input.value.trim()) add(input.value); }
    else if (e.key === "Escape") { hide(); }
    else if (e.key === "Backspace" && !this.value && tags.length) { tags.pop(); renderChips(); }
  });
  input.addEventListener("blur", function () { setTimeout(function () { if (input.value.trim()) add(input.value); }, 120); });
  return {
    get: function () { return tags.slice(); },
    set: function (a) { tags = (a || []).slice(); input.value = ""; hide(); renderChips(); }
  };
}
var includePicker = makeTagPicker("incInput", "incField", "incSuggest", refreshViewSummary);
var excludePicker = makeTagPicker("excInput", "excField", "excSuggest", refreshViewSummary);
function refreshViewSummary() {
  var el = document.getElementById("viewSummary");
  if (!el) return;
  el.textContent = describeView({
    query: currentQuery.trim(), includeTags: includePicker.get(), excludeTags: excludePicker.get(),
    filter: currentFilter, sort: currentSort
  });
}

