// ---- preserved page copy (snapshot) ----
// A snapshot preserves a readable copy of the page content at capture time, so it
// stays available even if the live page changes or disappears. In this prototype
// the captured content is simulated from the page's known details.
function fmtDate(ts) {
  try { return new Date(ts).toLocaleString(); } catch (e) { return "" + ts; }
}
function simulateCapture(it) {
  return "# " + it.title + "\n\n" +
    (it.description ? it.description + "\n\n" : "") +
    "This is a preserved, readable copy of the page as it was when you saved it. " +
    "It stays available even if the original page later changes or goes offline.\n\n" +
    "- Key point captured from the article\n- A second noted detail\n- A third takeaway\n\n" +
    "*(Prototype note: the copy's body text is simulated — the real app would store the actual page content.)*";
}
function snapshotAction(action, id) {
  var arr = load(), changed = null;
  for (var i = 0; i < arr.length; i++) {
    if (arr[i].id === id) {
      if (action === "save" || action === "update") {
        arr[i].snapshot = { capturedAt: Date.now(), content: simulateCapture(arr[i]) };
      } else if (action === "remove") {
        delete arr[i].snapshot;
      }
      changed = arr[i];
    }
  }
  persist(arr); render();
  flash(action === "remove" ? "Saved copy removed." : (action === "update" ? "Saved copy updated." : "Copy saved."), "ok");
}
var snapOverlay = document.getElementById("snapOverlay");
function openSnapshot(item) {
  document.getElementById("snapHead").textContent = item.title + " — saved copy";
  document.getElementById("snapBanner").textContent = "Preserved copy captured on " + fmtDate(item.snapshot.capturedAt) + ". This may differ from the live page.";
  document.getElementById("snapView").innerHTML = mdToHtml(item.snapshot.content);
  document.getElementById("snapOriginal").href = item.url;
  snapOverlay.classList.add("show");
}
document.getElementById("snapClose").addEventListener("click", function () { snapOverlay.classList.remove("show"); });
snapOverlay.addEventListener("click", function (e) { if (e.target === snapOverlay) snapOverlay.classList.remove("show"); });

// ---- note viewer (read-only, rendered Markdown) ----

