function snapshotAction(action, id) {
  var arr = load(), msg = "";
  for (var i = 0; i < arr.length; i++) {
    if (arr[i].id === id) {
      if (action === "save" || action === "update") {
        if (isPdfUrl(arr[i].url)) {
          arr[i].snapshot = { capturedAt: Date.now(), kind: "pdf" };
          msg = action === "update" ? "Saved PDF updated." : "PDF saved.";
        } else {
          arr[i].snapshot = { capturedAt: Date.now(), kind: "page", content: simulateCapture(arr[i]) };
          msg = action === "update" ? "Saved copy updated." : "Copy saved.";
        }
      } else if (action === "remove") {
        delete arr[i].snapshot; msg = "Saved copy removed.";
      }
    }
  }
  persist(arr); render(); flash(msg, "ok");
}
function archiveOnlineAction(action, id) {
  var arr = load(), msg = "";
  for (var i = 0; i < arr.length; i++) {
    if (arr[i].id === id) {
      if (action === "add") {
        var ts = new Date().toISOString().replace(/[-:T]/g, "").slice(0, 14);
        arr[i].archiveUrl = "https://web.archive.org/web/" + ts + "/" + arr[i].url;
        arr[i].archivedAt = Date.now();
        msg = "Preserved on the Internet Archive.";
      } else if (action === "remove") {
        delete arr[i].archiveUrl; delete arr[i].archivedAt; msg = "Internet Archive link removed.";
      }
    }
  }
  persist(arr); render(); flash(msg, "ok");
}

