  var payload = { app: "my-bookmarks", version: 1, exportedAt: new Date().toISOString(), bookmarks: load() };
  downloadFile("bookmarks-backup.json", JSON.stringify(payload, null, 2), "application/json");
  flash("Backup exported.", "ok");
});
document.getElementById("exportHtml").addEventListener("click", function () {
  var rows = load().map(function (b) {
    var add = Math.floor((b.savedAt || Date.now()) / 1000);
    var tags = (b.tags || []).join(",");
    return '    <DT><A HREF="' + escAttr(b.url) + '" ADD_DATE="' + add + '"' +
      (tags ? ' TAGS="' + escAttr(tags) + '"' : "") + '>' + escAttr(b.title || b.url) + '</A>';
  }).join("\n");
  var html = "<!DOCTYPE NETSCAPE-Bookmark-file-1>\n" +
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n' +
    "<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n" + rows + "\n</DL><p>\n";
  downloadFile("bookmarks.html", html, "text/html");
  flash("Bookmarks exported.", "ok");
});

function mergeImported(incoming) {
  var existing = load();
  var seen = {}; existing.forEach(function (b) { seen[b.norm || normalize(b.url)] = true; });
  var added = 0, skipped = 0, i = 0;
  incoming.forEach(function (b) {
    if (!b || !b.url || !isValidWebUrl(b.url)) { skipped++; return; }
    var n = normalize(b.url);
    if (seen[n]) { skipped++; return; }
    seen[n] = true; b.norm = n; b.id = "imp" + Date.now() + "_" + (i++);
    existing.push(b); added++;
  });
  persist(existing); renderViewsChips(); render();
  return { added: added, skipped: skipped };
}
function importJson(text) {
  var data = JSON.parse(text);
  var list = Array.isArray(data) ? data : (data.bookmarks || []);
  return mergeImported(list.map(function (b) {
    var vis = (b.icon && b.preview) ? { icon: b.icon, preview: b.preview } : deriveVisual(b.url || "");
    return {
      url: b.url, title: b.title || b.url, description: b.description || "",
      icon: vis.icon, preview: vis.preview,
      tags: Array.isArray(b.tags) ? b.tags.map(function (t) { return normalizeTag(t); }).filter(Boolean) : [],
      note: b.note || "", toRead: b.toRead === true, archived: b.archived === true,
      snapshot: b.snapshot || undefined, archiveUrl: b.archiveUrl || undefined, archivedAt: b.archivedAt || undefined,
      savedAt: b.savedAt || Date.now(), editedAt: b.editedAt || null
    };
  }));
}
function importHtml(text) {
  var doc = new DOMParser().parseFromString(text, "text/html");
  var anchors = Array.prototype.slice.call(doc.querySelectorAll("a"));
  return mergeImported(anchors.map(function (a) {
    var url = a.getAttribute("href") || "";
    var vis = deriveVisual(url);
    var tags = (a.getAttribute("tags") || a.getAttribute("TAGS") || "").split(",").map(function (t) { return normalizeTag(t); }).filter(Boolean);
    var add = parseInt(a.getAttribute("add_date") || a.getAttribute("ADD_DATE") || "0", 10);
    return {
      url: url, title: (a.textContent || url).trim(), description: "",
      icon: vis.icon, preview: vis.preview, tags: tags, note: "",
      toRead: false, archived: false, savedAt: add ? add * 1000 : Date.now(), editedAt: null
    };
  }).filter(function (b) { return b.url; }));
}
document.getElementById("importFile").addEventListener("change", function (e) {
  var file = e.target.files && e.target.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function () {
    var text = String(reader.result || ""); var res, out = document.getElementById("importResult");
    try {
      var isJson = /\.json$/i.test(file.name) || /^\s*[\[{]/.test(text);
      res = isJson ? importJson(text) : importHtml(text);
      out.textContent = "Imported " + res.added + (res.added === 1 ? " bookmark" : " bookmarks") +
        (res.skipped ? ", skipped " + res.skipped + " (duplicates or invalid)." : ".");
      flash("Imported " + res.added + " bookmark" + (res.added === 1 ? "" : "s") + ".", "ok");
    } catch (err) {
      out.textContent = "Sorry, that file couldn't be read as bookmarks.";
    }
    e.target.value = "";
  };
  reader.readAsText(file);
});

// ---- settings panel ----
var settingsOverlay = document.getElementById("settingsOverlay");

