input.content:
:root {
  --bg: #f6f7f9; --card: #fff; --ink: #1f2430; --muted: #6b7280; --line: #e5e7eb;
  --accent: #2f6feb; --accent-ink: #fff;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--ink); }
[hidden] { display: none !important; }

button { font-family: inherit; }
.primary { background: var(--accent); color: var(--accent-ink); border: none; border-radius: 9px; padding: 11px 18px; font-size: 15px; font-weight: 600; cursor: pointer; }
.ghost { background: #fff; color: var(--ink); border: 1px solid var(--line); border-radius: 9px; padding: 9px 13px; font-size: 13px; font-weight: 600; cursor: pointer; }
.ghost:hover { background: #f5f8ff; }
.danger { color: #dc2626; }
.danger.solid { background: #dc2626; color: #fff; border: none; border-radius: 9px; padding: 10px 16px; font-weight: 600; cursor: pointer; }

/* Auth */
.auth { min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 16px; }
.authCard { background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 28px; width: 100%; max-width: 400px; box-shadow: 0 12px 40px rgba(0,0,0,.06); }
.authCard h1 { margin: 0 0 4px; font-size: 24px; }
.authCard .sub { margin: 0 0 18px; color: var(--muted); font-size: 14px; }
.tabs { display: flex; gap: 6px; margin-bottom: 16px; }
.tab { flex: 1; padding: 9px; border: 1px solid var(--line); background: #fff; color: var(--muted); border-radius: 9px; font-weight: 600; cursor: pointer; }
.tab.active { background: var(--accent); color: #fff; border-color: var(--accent); }
#authForm { display: flex; flex-direction: column; gap: 12px; }
#authForm label { display: flex; flex-direction: column; gap: 5px; font-size: 13px; color: var(--muted); font-weight: 600; }
#authForm input { padding: 11px; font-size: 15px; border: 1px solid var(--line); border-radius: 9px; }
.authErr { color: #b91c1c; font-size: 13px; min-height: 1px; }
.reviewHint { margin: 14px 0 0; font-size: 12px; color: var(--muted); background: #f6f7f9; border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }

/* App shell */
header { padding: 20px 16px 8px; max-width: 860px; margin: 0 auto; }
header h1 { font-size: 22px; margin: 0 0 2px; }
header .sub { margin: 0; color: var(--muted); font-size: 13px; }
.headRow { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.headBtns { display: flex; gap: 8px; flex: 0 0 auto; }
main { max-width: 860px; margin: 0 auto; padding: 8px 16px 60px; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 14px; display: flex; gap: 8px; flex-wrap: wrap; margin: 12px 0 6px; }
.saver input[type=text] { flex: 1 1 260px; min-width: 0; padding: 12px; font-size: 15px; border: 1px solid var(--line); border-radius: 9px; outline: none; }
.saver input[type=text]:focus { border-color: var(--accent); }
.saverErr { color: #b91c1c; font-size: 13px; margin: 0 2px 10px; min-height: 1px; }

.viewsBar { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin: 6px 0 12px; }
.viewsLabel { font-size: 12px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: .03em; }
.viewChip { display: inline-flex; align-items: center; background: #fff; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; }
.viewChip button { border: none; background: none; cursor: pointer; font-size: 13px; font-weight: 600; }
.viewChip .open { padding: 6px 4px 6px 12px; color: var(--ink); }
.viewChip .open:hover { color: var(--accent); }
.viewChip .del { padding: 6px 10px 6px 4px; color: var(--muted); }
.viewChip .del:hover { color: #dc2626; }
.viewSaveBtn { padding: 6px 12px; font-size: 13px; font-weight: 600; border: 1px dashed var(--line); background: #fff; color: var(--accent); border-radius: 999px; cursor: pointer; }

.searchbar { margin-bottom: 6px; }
.searchbar input { width: 100%; padding: 11px 12px; font-size: 15px; border: 1px solid var(--line); border-radius: 9px; outline: none; background: #fff; }
.searchbar input:focus { border-color: var(--accent); }
.hint { font-size: 12px; color: var(--muted); margin: 0 2px 12px; }
.hint code { background: #eef2ff; border: 1px solid #dbe4ff; border-radius: 5px; padding: 1px 5px; font-size: 11px; }
.activeTags { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 2px 12px; font-size: 13px; color: var(--muted); }
.activeTags .atg { background: #eef2ff; border: 1px solid #dbe4ff; color: #3730a3; border-radius: 999px; padding: 2px 9px; font-weight: 600; font-size: 12px; }
.activeTags .atg.exc { background: #fdecec; border-color: #f6c9c9; color: #9b2c2c; }
.activeTags .clearTags { background: none; border: none; color: var(--accent); font-weight: 600; cursor: pointer; font-size: 13px; }

.flash { border-radius: 9px; font-size: 14px; margin-bottom: 12px; padding: 10px 12px; display: none; }
.flash.ok { background: #ecfdf5; border: 1px solid #a7f3d0; color: #065f46; }
.flash.info { background: #eff6ff; border: 1px solid #bfdbfe; color: #1e40af; }
.flash.err { background: #fef2f2; border: 1px solid #fecaca; color: #991b1b; }

.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin: 2px 0 12px; }
.filters { display: flex; gap: 6px; flex-wrap: wrap; }
.filters button { padding: 7px 13px; font-size: 13px; font-weight: 600; border: 1px solid var(--line); background: #fff; color: var(--muted); border-radius: 999px; cursor: pointer; }
.filters button.active { background: var(--accent); color: #fff; border-color: var(--accent); }
.toolRight { display: flex; align-items: center; gap: 10px; }
.sortLabel { font-size: 13px; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }
.sortLabel select, .setSelect { font-size: 13px; padding: 7px 8px; border: 1px solid var(--line); border-radius: 8px; background: #fff; color: var(--ink); cursor: pointer; }
.setSelect { width: 100%; padding: 10px; font-size: 14px; }

.bulkBar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; background: #eef4ff; border: 1px solid #cfe0ff; border-radius: 10px; padding: 10px 12px; margin: 0 0 12px; }
.bulkBar .bulkCount { font-weight: 700; font-size: 13px; color: #1e3a8a; }
.bulkBar button { padding: 7px 11px; font-size: 13px; font-weight: 600; border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 8px; cursor: pointer; }
.bulkBar button.danger { border-color: #f3c0c0; }
.bulkBar .bulkTag { display: inline-flex; gap: 6px; }
.bulkBar .bulkTag input { padding: 6px 9px; font-size: 13px; border: 1px solid var(--line); border-radius: 8px; width: 120px; }

.count { color: var(--muted); font-size: 13px; margin: 0 2px 10px; }
ul.list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
li.item { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 12px 14px; display: flex; align-items: flex-start; gap: 12px; }
li.item.flash-existing { outline: 2px solid var(--accent); outline-offset: 1px; }
li.item.archived { opacity: .72; }
li.item.selected { outline: 2px solid var(--accent); outline-offset: 1px; }
li.item .selBox { flex: 0 0 auto; width: 20px; height: 20px; align-self: center; cursor: pointer; }
.thumb { width: 92px; height: 62px; flex: 0 0 auto; border-radius: 8px; background-size: cover; background-position: center; border: 1px solid var(--line); }
.item .body { min-width: 0; flex: 1 1 auto; }
.item .titleRow { display: flex; align-items: center; gap: 7px; }
.item .fav { width: 18px; height: 18px; border-radius: 4px; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; color: #fff; font-size: 11px; font-weight: 700; }
.item .title { font-size: 15px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.item .chip { font-size: 11px; font-weight: 700; color: var(--accent); background: #eef2ff; border: 1px solid #dbe4ff; border-radius: 999px; padding: 1px 8px; flex: 0 0 auto; }
.item .desc { font-size: 13px; color: #374151; margin: 3px 0 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.item .url { font-size: 12px; color: var(--muted); margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.item a.open { color: inherit; text-decoration: none; }
.item a.open:hover .title { text-decoration: underline; }
.item .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
